import sys
import re
import os
import math

def validate_expression(expr):
    if not re.fullmatch(r'^[0-9+\-*/(). ]+$', expr):
        return False
    stack = []
    for c in expr:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return len(stack) == 0

def evaluate_expression(expr):
    try:
        # Replace spaces with empty string and evaluate
        expr = expr.replace(' ', '')
        if expr == '':
            return 0
        # Use eval with caution, but we've already validated the expression
        return eval(expr, {'__builtins__': None}, {})
    except ZeroDivisionError:
        return None
    except:
        return None

def process_record(name, template):
    # Split into name and template parts
    if '=' not in name:
        return None
    name_part, template_part = name.split('=', 1)
    if not re.fullmatch(r'^[a-z][a-z0-9_]*$', name_part):
        return None

    # Find all placeholders
    placeholders = re.findall(r'\{\{([^}]+)\}\}', template_part)
    if not placeholders:
        return None

    # Validate each placeholder expression
    for expr in placeholders:
        if not validate_expression(expr):
            return f"error: {name}: {expr}"

    # Evaluate each placeholder
    rendered = template_part
    for i, expr in enumerate(placeholders):
        result = evaluate_expression(expr)
        if result is None:
            return f"error: {name}: {expr}"
        rendered = rendered.replace(f'{{{{{i+1}}}}}', str(result))

    return rendered

def compute_tag(text, key):
    if not key:
        return None
    try:
        key_int = int(key, 16)
    except ValueError:
        return None
    hash_val = hash(text + key)
    hex_digits = format(hash_val, 'x')
    return hex_digits.zfill(16)

def main():
    if 'RENDERER_KEY' not in os.environ or not os.environ['RENDERER_KEY']:
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

    key = os.environ['RENDERER_KEY']
    failed = False

    for line in sys.stdin:
        line = line.strip()
        if not line or line.isspace():
            continue

        name_template = line.split('=', 1)
        if len(name_template) != 2:
            continue

        name, template = name_template
        result = process_record(name, template)

        if isinstance(result, str) and result.startswith('error:'):
            print(result, file=sys.stderr)
            failed = True
        elif result is not None:
            rendered = result
            tag = compute_tag(f"{name}={rendered}", key)
            if tag is not None:
                print(f"{name}={rendered}|{tag}")

    sys.exit(1 if failed else 0)

if __name__ == "__main__":
    main()

import sys
import os
import re
from functools import reduce

def evaluate_expression(expr):
    try:
        return int(re.sub(r'\s+', '', expr))
    except ValueError:
        return 0

def render_template(template, key):
    def replace_placeholder(match):
        expr = match.group(1)
        value = evaluate_expression(expr)
        return str(value)

    rendered = re.sub(r'\{\{(\d+[+\-*/()\s]*)\}\}', replace_placeholder, template)
    return rendered

def compute_tag(text, key):
    if not key:
        return ""
    combined = text + key
    return combined.encode('utf-8').hex()

def main():
    if not os.getenv('RENDERER_KEY'):
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

