    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, template = line.split('=', 1)
        rendered = render_template(template, key)
        output = f"{name}={rendered}"
        tag = compute_tag(output, key)
        print(f"{output}|{tag[:16].lower()}")

