import sys
import os
import re
import hashlib

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return 0

def compute_tag(text, secret):
    combined = text + secret
    return hashlib.sha256(combined.encode()).hexdigest()[:16].lower()

def main():
    secret = os.getenv('RENDERER_KEY')
    if not secret:
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        match = re.fullmatch(r'([^=]+)=([^ ]+)', line)
        if not match:
            continue
        name, expr = match.groups()
        if not name or not re.fullmatch(r'[0-9+-*() ]+', expr):
            continue
        value = evaluate_expression(expr)
        tag = compute_tag(name, secret)
        print(f"{name}={value}|{tag}")

if __name__ == "__main__":
    main()

